24|// Per-row sum: walk row by row. Each row is contiguous in memory so the
25|// access pattern is good. This is the obvious "right" way to do it.
26|std::vector<double> Matrix::SumPerRow() const {
27|    std::vector<double> result(rows_, 0.0);
28|    for (std::size_t r = 0; r < rows_; ++r) {
29|        double s = 0.0;
30|        for (std::size_t c = 0; c < cols_; ++c) {
31|            s += at(r, c);
32|        }
33|        result[r] = s;
34|    }
35|    return result;
36|}
